(7545850, 1208223, 124815, '<td valign="top">What''s really delightful in this real doll is the slackness of her eyebrows; the little imperfections are always a good sign</td>', 'What''s really delightful in this real doll is the slackness of her eyebrows; the little imperfections are always a good sign', '2017-11-21 23:10:54.000000', NULL, 1),
(7545851, 1208189, 173844, '<td valign="top">Lustrous, beautiful, ethereal image.  I like that angled smile and her kind eyes.  Like a presence at a seance.  I also like how the sepia tones flow into each other.  High class.</td>', 'Lustrous, beautiful, ethereal image.  I like that angled smile and her kind eyes.  Like a presence at a seance.  I also like how the sepia tones flow into each other.  High class.', '2017-11-21 23:11:39.000000', NULL, 1),
(7545853, 1208168, 173844, '<td valign="top">The portrait aspect of this image is minimal, but her pose is fascinating in its resemblance to an Egyptian hieroglyph -  holding a cell phone, no less.  I also think the composition is good.  Interesting entry.</td>', 'The portrait aspect of this image is minimal, but her pose is fascinating in its resemblance to an Egyptian hieroglyph -  holding a cell phone, no less.  I also think the composition is good.  Interesting entry.', '2017-11-21 23:15:30.000000', NULL, 1),
(7545856, 1208220, 83313, '<td valign="top">This just looks creepy. It''s like he''s a mannequin and I''m suck in a staring contest with him. High vote for that visual impact.</td>', 'This just looks creepy. It''s like he''s a mannequin and I''m suck in a staring contest with him. High vote for that visual impact.', '2017-11-21 23:21:23.000000', NULL, 1),
