(7545894, 1207973, 132898, '<td valign="top">Wow. My first entry in five years...I am overwhelmed<br/>This guy is my friend, a gentleman and a gentle man, a bird photographer who gets me up early to go out shooting, often in the cold. And he is always wearing that toque. <br/>His wife knit it for him over 40 years ago. <br/>So when I set out to take his portrait, it had to be with that toque...</td>', 'Wow. My first entry in five years...I am overwhelmedThis guy is my friend, a gentleman and a gentle man, a bird photographer who gets me up early to go out shooting, often in the cold. And he is always wearing that toque. His wife knit it for him over 40 years ago. So when I set out to take his portrait, it had to be with that toque...', '2017-11-22 00:53:58.000000', NULL, 0),
(7545925, 1207973, 135744, '<td valign="top">What a superb result for your return to DPC!!! And a superb photo too. The lighting and subject are both perfect. Congrats!</td>', 'What a superb result for your return to DPC!!! And a superb photo too. The lighting and subject are both perfect. Congrats!', '2017-11-22 06:31:10.000000', NULL, 0),
(7545927, 1208161, 135744, '<td valign="top">Congrats Mark. Superb photography!</td>', 'Congrats Mark. Superb photography!', '2017-11-22 06:32:17.000000', NULL, 0),
(7545928, 1208194, 135744, '<td valign="top">Congrats - really great lighting and perfectly captured.</td>', 'Congrats - really great lighting and perfectly captured.', '2017-11-22 06:32:39.000000', NULL, 0),
(7545929, 1208201, 163430, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by kiwinick:</b></div><hr/><i> looks like a Passport shot... </i></td></tr></table> <br/> <br/>I only wish i looked like this on my passport photo. There is a saying that goes "If you look like your passport photo, seek medical attention. There is a chance that you are sick". Maybe it''s deliberate, so when you show your passport to the border officials, after a 16 hour three layover flight and a random strip search, you look exactly like the photo.</td>', 'Originally posted by kiwinick: looks like a Passport shot...   I only wish i looked like this on my passport photo. There is a saying that goes "If you look like your passport photo, seek medical attention. There is a chance that you are sick". Maybe it''s deliberate, so when you show your passport to the border officials, after a 16 hour three layover flight and a random strip search, you look exactly like the photo.', '2017-11-22 06:33:45.000000', NULL, 0),
(7545930, 1208142, 135744, '<td valign="top">That dude has character and you have captured it so well. Congrats on the HM!</td>', 'That dude has character and you have captured it so well. Congrats on the HM!', '2017-11-22 06:57:33.000000', NULL, 0),
(7545931, 1207973, 32108, '<td valign="top">Beautifully done, congratulations.</td>', 'Beautifully done, congratulations.', '2017-11-22 07:02:09.000000', NULL, 0),
(7545932, 1208176, 32108, '<td valign="top">Normally I''d say taking portraits of kids for a competition is cheating ''cause they''re always so cute but on this occasion you have put all the elements together for an excellent capture, well done.</td>', 'Normally I''d say taking portraits of kids for a competition is cheating ''cause they''re always so cute but on this occasion you have put all the elements together for an excellent capture, well done.', '2017-11-22 07:06:29.000000', NULL, 0),
(7545933, 1208161, 32108, '<td valign="top">Your model + your skills have combined for a great portrait, congrats.</td>', 'Your model + your skills have combined for a great portrait, congrats.', '2017-11-22 07:07:57.000000', NULL, 0),
(7545934, 1208142, 32108, '<td valign="top">The pose feels contrary to his obvious current position and serves to make this portrait intriguing, congratulations.</td>', 'The pose feels contrary to his obvious current position and serves to make this portrait intriguing, congratulations.', '2017-11-22 07:10:34.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7545939, 1208194, 109227, '<td valign="top">Lovely light and expression.  Congrats on the HM.</td>', 'Lovely light and expression.  Congrats on the HM.', '2017-11-22 08:19:07.000000', NULL, 0),
(7545940, 1208161, 109227, '<td valign="top">Congrats Mark; you do B&amp;W so well.</td>', 'Congrats Mark; you do B&W so well.', '2017-11-22 08:20:28.000000', NULL, 0),
(7545944, 1208201, 19825, '<td valign="top">I liked your entry (gave it a 7). The outtake has a bit more drama, but I like the connection to the eyes in the entry.</td>', 'I liked your entry (gave it a 7). The outtake has a bit more drama, but I like the connection to the eyes in the entry.', '2017-11-22 09:36:25.000000', NULL, 0),
(7545948, 1208156, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that contributes well to the challenge<br/> <br/>The lighting is good to the extent that it clearly defines the subjects features against the black background. I would like to see the eyes. The eyes are always such a strong draw in any portrait it would enhance the end result a lot, without them it feels a little manikin-like without soul. I take it all back! A closer inspection has revealed the eyes, that makes it work so much better now. Given how hard the eyes are to see I wonder how many others moved on before seeing them? <br/> <br/>A great mono portrait that fulfils the challenge brief well.</td>', 'Hello from the critique club An appealing image that contributes well to the challenge The lighting is good to the extent that it clearly defines the subjects features against the black background. I would like to see the eyes. The eyes are always such a strong draw in any portrait it would enhance the end result a lot, without them it feels a little manikin-like without soul. I take it all back! A closer inspection has revealed the eyes, that makes it work so much better now. Given how hard the eyes are to see I wonder how many others moved on before seeing them?  A great mono portrait that fulfils the challenge brief well.', '2017-11-22 10:22:23.000000', NULL, 0),
(7545951, 1208161, 182284, '<td valign="top">Awesome, big congrats.</td>', 'Awesome, big congrats.', '2017-11-22 10:35:00.000000', NULL, 0),
(7545952, 1207764, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that contributes well to the challenge<br/> <br/>A great capture, the two people are of course what makes this work so well. I have to agree with everything streetpigeon says, their lovely broad smily faces draw you right in there. The rest of the image forms an interesting backdrop especially with the mural out of which the cafe emerges. Well seen and captured Peter<br/></td>', 'Hello from the critique club An appealing image that contributes well to the challenge A great capture, the two people are of course what makes this work so well. I have to agree with everything streetpigeon says, their lovely broad smily faces draw you right in there. The rest of the image forms an interesting backdrop especially with the mural out of which the cafe emerges. Well seen and captured Peter', '2017-11-22 10:45:11.000000', NULL, 0),
(7545959, 1207973, 52549, '<td valign="top">So glad this ribboned, it''s a beautiful portrait. Huge congrats on your first ribbon and new PB, Maggie.</td>', 'So glad this ribboned, it''s a beautiful portrait. Huge congrats on your first ribbon and new PB, Maggie.', '2017-11-22 13:05:04.000000', NULL, 0),
(7545961, 1208176, 52549, '<td valign="top">Amazing image and wonderful portrait. Those eyes, the eyelashes... Another beauty from you, Paul. Congrats.</td>', 'Amazing image and wonderful portrait. Those eyes, the eyelashes... Another beauty from you, Paul. Congrats.', '2017-11-22 13:08:52.000000', NULL, 0),
(7545963, 1208161, 52549, '<td valign="top">Congrats again, Mark. Stunning image.</td>', 'Congrats again, Mark. Stunning image.', '2017-11-22 13:14:17.000000', NULL, 0),
(7545965, 1208194, 52549, '<td valign="top">As I said.. Fabulous portrait.</td>', 'As I said.. Fabulous portrait.', '2017-11-22 13:18:26.000000', NULL, 0),
(7545967, 1208070, 67697, '<td valign="top">I was glad her eyes weren''t open. She doesn''t need to make a connection with me. But I get to see her lost in the moment. That''s something that is not often captured.</td>', 'I was glad her eyes weren''t open. She doesn''t need to make a connection with me. But I get to see her lost in the moment. That''s something that is not often captured.', '2017-11-22 13:28:13.000000', NULL, 0),
(7545969, 1207916, 16148, '<td valign="top">Beautiful work.  Congratulations!</td>', 'Beautiful work.  Congratulations!', '2017-11-22 14:22:12.000000', NULL, 0),
(7545970, 1208176, 16148, '<td valign="top">Really well done!  Love the out of focus environmental details behind her.</td>', 'Really well done!  Love the out of focus environmental details behind her.', '2017-11-22 14:25:21.000000', NULL, 0),
(7545974, 1208194, 124815, '<td valign="top">I liked it a lot and like even more the color original. Great atmosphere</td>', 'I liked it a lot and like even more the color original. Great atmosphere', '2017-11-22 14:57:12.000000', NULL, 0),
(7545975, 1208197, 124815, '<td valign="top">I love this portrait and I think that, knowing the Bear electronically, the choice of showing him as part of an intricate design is extremely subtle and appropriate. His mind is a web of info, his eyes are forever searching and forever brooding and the lines on his face are telling a lot of stories.<br/>Showing him like a tapestry (a look that he often favors in his photographic work) is a beautiful tribute.</td>', 'I love this portrait and I think that, knowing the Bear electronically, the choice of showing him as part of an intricate design is extremely subtle and appropriate. His mind is a web of info, his eyes are forever searching and forever brooding and the lines on his face are telling a lot of stories.Showing him like a tapestry (a look that he often favors in his photographic work) is a beautiful tribute.', '2017-11-22 15:03:40.000000', NULL, 0),
(7545976, 1208189, 124815, '<td valign="top">It was a 9 from me, although I thought that I marked it 10.<br/>You and Penny outdid each other!</td>', 'It was a 9 from me, although I thought that I marked it 10.You and Penny outdid each other!', '2017-11-22 15:11:00.000000', NULL, 0),
(7546068, 1208194, 68504, '<td valign="top">Oh the personality just shines in this one. Thank you.</td>', 'Oh the personality just shines in this one. Thank you.', '2017-11-23 03:29:43.000000', NULL, 0),
